	CONSTRAINT "article_purge_end_evidence" CHECK("article_purge_executor_ends"."holder_mode" IN ('mapped_executor','manual_help') AND "article_purge_executor_ends"."evidence_kind"='holder_acknowledgement' AND "article_purge_executor_ends"."all_actions_stopped"=1 AND "article_purge_executor_ends"."all_actions_settled"=1 AND "article_purge_executor_ends"."server_verified"=0)
