-- Confirmed article-content purge guards.
-- Normal execution history remains immutable. The only deletion exception is
-- an owner-confirmed exact article snapshot with matching live operation/article
-- locks. No runtime disables a trigger, creates an executor-end proof, or clears
-- an unresolved external holder. Source fences contain identities only.
CREATE TRIGGER article_content_fences_authorized_insert BEFORE INSERT ON article_content_fences
WHEN NOT (EXISTS(SELECT 1 FROM article_deletions x JOIN article_list_deletions o ON o.id=x.operation_id AND o.owner=x.owner
 WHERE x.owner=NEW.owner AND x.id=NEW.article_id AND x.state='deleting' AND o.scope='all_articles' AND o.state='deleting'
 AND o.confirmed_at IS NOT NULL AND o.lock_token IS NOT NULL AND x.lock_token=o.lock_token
 AND x.lock_expires>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND o.lock_expires>strftime('%Y-%m-%dT%H:%M:%fZ','now')
 AND EXISTS(SELECT 1 FROM json_each(CASE WHEN json_valid(o.snapshot_json) THEN o.snapshot_json ELSE '[]' END) j WHERE json_extract(j.value,'$.id')=x.id))) OR NOT EXISTS(SELECT 1 FROM article_deletions x WHERE x.owner=NEW.owner AND x.id=NEW.article_id AND x.operation_id=NEW.operation_id)
BEGIN SELECT RAISE(ABORT,'article_purge_confirmation_required'); END;
